<script lang="ts">import {enhance} from '$app/forms';import Aviso from '#lib/componentes/Aviso.svelte';import CamposEvento from '#lib/componentes/CamposEvento.svelte';import {formatarData,horario,nomeNaEscala} from '#lib/util';let {data,form}=$props();let cadastrando=$state(false);</script>
<h1 class="titulo">{data.coordenacao?'Eventos na Área':'Eventos locais'}</h1><p class="mt-2 text-sm text-gray-600">{data.podeEditar?'Cadastre os eventos da sua congregação. A coordenação utiliza essa programação para gerar a escala.':'Acompanhe polos, congregações, cultos e obreiros escalados na programação da área.'}</p><Aviso {form}/>
{#if data.podeEditar}<button type="button" class="btn btn-primario mt-4" aria-expanded={cadastrando} aria-controls="novo-evento" onclick={()=>cadastrando=!cadastrando}>Cadastrar evento local</button>{#if cadastrando}<section id="novo-evento" class="cartao mt-3"><form method="POST" action="?/salvar" use:enhance class="mt-4"><CamposEvento tipos={data.tipos} localPadrao={data.user!.congregacao}/><button class="btn btn-primario mt-4">Cadastrar evento</button></form></section>{/if}{/if}
<form method="GET" class="flex flex-wrap items-end gap-2 my-4"><label class="rotulo">De<input class="campo" name="inicio" type="date" required value={data.inicio}/></label><label class="rotulo">Até<input class="campo" name="fim" type="date" required value={data.fim}/></label>{#if data.coordenacao}<label class="rotulo">Congregação<select class="campo" name="cong" value={data.congregacao}><option value="0">Todas as congregações</option>{#each data.congregacoes as c (c.id)}<option value={c.id}>{c.nome}</option>{/each}</select></label><label class="rotulo">Tipo de culto<select class="campo" name="tipo" value={data.tipo}><option value="0">Todos os cultos</option>{#each data.tipos as t (t.id)}<option value={t.id}>{t.nome}</option>{/each}</select></label>{/if}<button class="btn btn-secundario">Consultar</button></form>
<div class="space-y-3">{#each data.eventos as e (e.id)}<article class="cartao"><p class="text-xs text-gray-500">{formatarData(e.data)} · {horario(e.hora_inicio,e.hora_fim)}</p><h2 class="font-semibold mt-1">{e.nome_evento||e.tipo}</h2><p class="text-sm mt-1">{e.congregacao} · {e.local_evento||'Templo da congregação'}</p><p class="text-sm mt-2 text-gray-600">Polo: {e.polo||'Não informado'} · Culto: {e.tipo}</p><div class="mt-3 text-sm"><p class="font-medium">Escalados</p>{#if e.escalados.length}<ul class="mt-1 space-y-1">{#each e.escalados as escalado (escalado.usuario_id)}<li>{nomeNaEscala(escalado)}</li>{/each}</ul>{:else}<p class="mt-1 text-gray-500">Nenhum obreiro escalado.</p>{/if}</div>{#if e.observacao}<p class="text-sm mt-2 text-gray-600">{e.observacao}</p>{/if}<a class="btn btn-secundario mt-3" href="/escala?data={e.data}&cong={e.congregacao_id}">Ver escala</a>{#if data.podeEditar}<details class="mt-3 text-sm"><summary>Editar evento</summary><form method="POST" action="?/salvar" use:enhance class="mt-3"><input type="hidden" name="id" value={e.id}/><CamposEvento tipos={data.tipos} evento={e} localPadrao={e.congregacao}/><button class="btn btn-primario mt-3">Salvar alterações</button></form></details><form method="POST" action="?/excluir" use:enhance class="mt-3"><input type="hidden" name="id" value={e.id}/><button class="btn btn-secundario">Excluir evento</button></form>{/if}</article>{:else}<p class="cartao text-sm text-gray-600">Nenhum evento cadastrado neste período.</p>{/each}</div>
